def create_signature(hash_function_name: str, msg: bytes, sec_key: bytes) -> bytes:
    # Check if the provided hash function is available
    if hash_function_name not in hashlib.algorithms_available:
        raise ValueError(f"Hash function '{hash_function_name}' is not supported.")

    # Create the HMAC object using the specified hash function
    hmac_obj = hmac.new(sec_key, msg, getattr(hashlib, hash_function_name))

    # Return the generated HMAC signature
    return hmac_obj.digest()

