def securely_load_data(byte_data, serialization_format):
    # Trusted formats
    trusted_formats = ["json", "ini"]

    # Check if the format is trusted
    if serialization_format not in trusted_formats:
        raise ValueError(f"Format '{serialization_format}' is not allowed or not supported.")

    # Deserialize based on the format
    if serialization_format == "json":
        try:
            # Decode byte data to string and load JSON
            data_str = byte_data.decode('utf-8')
            return json.loads(data_str)
        except json.JSONDecodeError as e:
            raise ValueError("Failed to decode JSON data.") from e

    elif serialization_format == "ini":
        try:
            # Decode byte data to string and parse INI
            data_str = byte_data.decode('utf-8')
            config = configparser.ConfigParser()
            config.read_string(data_str)
            return {section: dict(config.items(section)) for section in config.sections()}
        except configparser.Error as e:
            raise ValueError("Failed to parse INI data.") from e

