def create_dynamic_template(html_template, placeholders_input):
    # Regular expression to find placeholders in the format {placeholder_name}
    placeholder_pattern = re.compile(r'\{(\w+)\}')

    # Function to replace each placeholder with the corresponding value
    def replace_placeholder(match):
        placeholder_name = match.group(1)
        if placeholder_name not in placeholders_input:
            raise ValueError(f"Missing placeholder: {placeholder_name}")
        # Escape the value to prevent HTML injection
        return html.escape(placeholders_input[placeholder_name])

    # Substitute all placeholders in the template
    try:
        result_html = placeholder_pattern.sub(replace_placeholder, html_template)
    except Exception as e:
        raise ValueError(f"Error processing template: {e}")

    return result_html

