def evaluate_expression_safely(expression: str) -> str:
    import re
    from collections import deque

    # Define allowed characters and operators
    allowed_chars = set("0123456789+-*/(). ")
    operators = set("+-*/")
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Check for invalid characters
    if not all(char in allowed_chars for char in expression):
        return "Unsafe Code Detected!"

    # Tokenize the expression
    def tokenize(expr):
        tokens = re.findall(r'\d+\.?\d*|[+*/()-]', expr)
        return tokens

    # Convert infix expression to postfix (RPN) using the Shunting Yard algorithm
    def infix_to_postfix(tokens):
        output = []
        stack = []
        for token in tokens:
            if token.isnumeric() or re.match(r'\d+\.\d*', token):  # numbers
                output.append(token)
            elif token in operators:
                while stack and stack[-1] in operators and precedence[stack[-1]] >= precedence[token]:
                    output.append(stack.pop())
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                stack.pop()  # pop '('
        while stack:
            output.append(stack.pop())
        return output

    # Evaluate the postfix expression
    def evaluate_postfix(postfix_tokens):
        stack = deque()
        for token in postfix_tokens:
            if token.isnumeric() or re.match(r'\d+\.\d*', token):  # numbers
                stack.append(float(token))
            elif token in operators:
                if len(stack) < 2:
                    return "Unsafe Code Detected!"
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        return "Unsafe Code Detected!"  # Avoid division by zero
                    stack.append(a / b)
        if len(stack) != 1:
            return "Unsafe Code Detected!"
        return str(stack.pop())

    try:
        tokens = tokenize(expression)
        postfix_tokens = infix_to_postfix(tokens)
        result = evaluate_postfix(postfix_tokens)
        return result
    except Exception:
        return "Unsafe Code Detected!"

